mapper.select:
select m.id, m.day_name, m.day_target, m.day_type, m.remind_type, m.repeat_flag, m.notify_status, m.next_notify_time, m.user_id, m.group_id, u.user_name, u.user_code, g.group_name, g.group_code from mes_msg_day_matter m left join mes_msg_user u on m.user_id = u.id and u.deleted_flag = '0' left join mes_msg_group g on m.group_id = g.id and g.deleted_flag = '0'
m.deleted_flag = '0'
and day_name like concat('%', #{param.dayName}, '%')
and day_type = #{param.dayType}
and m.user_id = #{param.userId}
and m.group_id = #{param.groupId}
order by m.update_time desc
